import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const n="/llamatron/assets/scene.CtU4nF31.svg",r="/llamatron/assets/scene_density.BifuNoG2.svg",c="/llamatron/assets/scene_swell.CWG7ju0Q.svg",S=JSON.parse('{"title":"Scenes","description":"","frontmatter":{},"headers":[],"relativePath":"SCENES.md","filePath":"SCENES.md"}'),i={name:"SCENES.md"};function h(d,e,l,p,g,f){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="scenes" tabindex="-1">Scenes <a class="header-anchor" href="#scenes" aria-label="Permalink to &quot;Scenes&quot;">​</a></h1><p>A scene is a row of Arrange: the clips that play together, with settings for the whole section. This page covers the Scene page.</p><p><img src="'+n+'" alt="The Scene page"></p><h2 id="scene-length" tabindex="-1">Scene Length <a class="header-anchor" href="#scene-length" aria-label="Permalink to &quot;Scene Length&quot;">​</a></h2><p>A scene starts all of its clips together and has no length of its own: a scene lasts as long as its longest clip that doesn&#39;t loop, times the scene&#39;s repeats.</p><h2 id="scene-settings" tabindex="-1">Scene Settings <a class="header-anchor" href="#scene-settings" aria-label="Permalink to &quot;Scene Settings&quot;">​</a></h2><p>On Arrange, <code>Enter</code> on a scene&#39;s name opens the Scene page.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td>The scene&#39;s name.</td></tr><tr><td>Scale</td><td>A scale for the scene&#39;s clips in place of the song&#39;s. <code>Bksp</code> goes back to the song&#39;s.</td></tr><tr><td>Groove</td><td>A groove for the scene&#39;s clips in place of the song&#39;s, or <code>off</code> to play them straight whatever the song or a track chooses. A track&#39;s own groove still wins over the scene&#39;s, but not over the scene&#39;s <code>off</code>. <code>Bksp</code> goes back to the song&#39;s.</td></tr><tr><td>Tempo</td><td>A tempo in place of the song&#39;s. <code>Bksp</code> goes back to the song&#39;s.</td></tr><tr><td>Tempo ramps to</td><td>Moves the tempo from Tempo to this value across the scene&#39;s repeats. <code>Bksp</code> turns the ramp off.</td></tr><tr><td>Repeat</td><td>Plays the whole scene this many times, from 1 to 999.</td></tr><tr><td>Chains</td><td>The chains every clip of the scene runs, after each clip&#39;s own, edited as a clip&#39;s are. See <a href="./CHAINS">Chains</a>.</td></tr><tr><td>Launch together</td><td>For real-time playback only, and on by default: when a clip above sends a start to any clip of this scene, every clip of the scene starts together. When off, each clip starts only when the clip directly above it sends a start, and Arrange marks the scene with <code>┆</code> after its name. <code>Space</code> or <code>Enter</code> toggles it. See <a href="./PLAYING_LIVE">Playing Live</a>.</td></tr><tr><td>Reset AX to Reset DX</td><td>Sets that register back to its default as the scene starts. <code>Space</code> or <code>Enter</code> toggles it. A scene that repeats resets only as it first starts, so a register can keep changing across the repeats.</td></tr><tr><td>+ Density, + Swell, + Articulate</td><td>Sections, closed until opened, each with a Start, End, Over and Then that shape every clip of the scene across the whole scene, unless a clip sets its own shape or a generator in its chains does. See <a href="./generators/DENSITY">Density</a>, <a href="./generators/SWELL">Swell</a> and <a href="./generators/ARTICULATE">Articulate</a>.</td></tr></tbody></table><p>The page shows how long the scene lasts, and any problem, such as every clip looping. Turning on a loop that leaves a scene with no clip that ends opens a Scene loop errors dialog naming the scenes to fix, and exporting while any scene is in that state does the same.</p><h2 id="section-shapes" tabindex="-1">Section Shapes <a class="header-anchor" href="#section-shapes" aria-label="Permalink to &quot;Section Shapes&quot;">​</a></h2><p>The Scene page&#39;s sections shape every clip of the scene over its length. In <code>examples/by_genre/electronic/edm_density.yml</code>, the intro&#39;s Density ramps from 25 to 100 across the scene, filling in to a build:</p><p><img src="'+r+'" alt="A scene&#39;s Density section open"></p><p>In <code>examples/learning/16_bolero_swell.yml</code>, each scene&#39;s Swell picks up where the one before ended, for one long crescendo:</p><p><img src="'+c+'" alt="A scene&#39;s Swell section open"></p>',14)])])}const _=t(i,[["render",h]]);export{S as __pageData,_ as default};
